// inOpen, inHigh, inLow and inClose are the histories, of one length.
//
// The error is [InsufficientHistory] for a history of at most
// [Core.CDLHIKKAKEMODLookback] bars, [OutOfRangeEndIndex] for one longer than
// [IndexMax]+1 bars, and [BadParam] for histories of different lengths.
func (c *Core) CDLHIKKAKEMODOpen(inOpen, inHigh, inLow, inClose []float64) (*CDLHIKKAKEMODStream, int32, error) {
	sp, err := c.cdlhikkakemodOpenInternal(inOpen, inHigh, inLow, inClose, 0)
	if err != nil {
		return nil, 0, err
	}
	return sp, sp.cur_outInteger, nil
}

// CDLHIKKAKEMODOpenAndFill opens a stream as [Core.CDLHIKKAKEMODOpen] does and
// also writes the outputs over the whole history, as [Core.CDLHIKKAKEMOD]
// writes them for bars 0 through len(inOpen)-1, returning that range.
//
// Each output must hold len(inOpen) minus [Core.CDLHIKKAKEMODLookback] values
// and share no memory with an input or another output.
//
// The errors are those of [Core.CDLHIKKAKEMODOpen], and [BadParam] for an
// output that is empty, too short or sharing memory.
func (c *Core) CDLHIKKAKEMODOpenAndFill(inOpen, inHigh, inLow, inClose []float64, outInteger []int32) (*CDLHIKKAKEMODStream, OutRange, error) {
	if len(inOpen) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.cdlhikkakemodLookback())
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	if len(inHigh) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	if len(inLow) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	if len(inClose) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inOpen)-lookback, 0)
	if len(outInteger) == 0 || len(outInteger) < outLen {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.cdlhikkakemodOpenAndFillInternal(inOpen, inHigh, inLow, inClose, 0, &outBegIdx, &outNBElement, outInteger)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
